/* @autogenerated */
import { fakeAsync, tick } from '@angular/core/testing';
import { Subject, of } from 'rxjs';
import { OidcIdentityHandlerService, OidcIdentityProviderService } from './oidc-identity-provider.service';
import { AppConfigService } from '@shared/context/config/app-config.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { ErrorService } from '@shared/context/observability/error.service';
import { IdentityUiPort } from '../identity-provider.interface';

function buildMocks(
  opts: {
    tenant?: string;
    identitySetup?: any;
    hasValidToken?: boolean;
    userProfile?: any;
    issuer?: string;
  } = {},
) {
  const eventSubject = new Subject<any>();

  const oauthService = jasmine.createSpyObj('OAuthService', [
    'initCodeFlow',
    'revokeTokenAndLogout',
    'refreshToken',
    'hasValidAccessToken',
    'getAccessToken',
    'loadUserProfile',
    'loadDiscoveryDocumentAndTryLogin',
    'configure',
    'setStorage',
    'logOut',
    'setupAutomaticSilentRefresh',
  ]);
  (oauthService as any).events = eventSubject.asObservable();
  oauthService.issuer = opts.issuer !== undefined ? opts.issuer : 'https://issuer.example.com';
  oauthService.hasValidAccessToken.and.returnValue(opts.hasValidToken ?? false);
  oauthService.getAccessToken.and.returnValue('test-access-token');
  oauthService.refreshToken.and.returnValue(Promise.resolve({}));
  oauthService.loadDiscoveryDocumentAndTryLogin.and.returnValue(Promise.resolve(true));
  const userProfile = opts.userProfile ?? { name: 'Test User', email: 'test@example.com', groups: ['admin'] };
  oauthService.loadUserProfile.and.returnValue(Promise.resolve({ info: userProfile }));

  const userInfoSpy = { set: jasmine.createSpy('userInfo.set') };
  const appState = {
    tenant: of(opts.tenant ?? 'main'),
    userInfo: { main: userInfoSpy },
  } as unknown as AppStateService;

  const identitySetup = opts.identitySetup ?? {
    redirect: 'http://localhost/callback',
    issuer: 'https://issuer.example.com',
    'force-https': false,
    'client-id': 'test-client',
    scope: 'openid',
  };
  const appConfig = { 'identity.main': of(identitySetup) } as unknown as AppConfigService;

  const errors = { notifyError: jasmine.createSpy('notifyError') } as unknown as ErrorService;

  const ui = jasmine.createSpyObj<IdentityUiPort>('IdentityUiPort', ['confirmResetCredentials', 'notifyError']);
  ui.confirmResetCredentials.and.returnValue(of(true));

  return { eventSubject, oauthService, appState, appConfig, errors, ui, userInfoSpy };
}

describe('OidcIdentityProviderService', () => {
  it('accept("oidc", ...) creates and returns an OidcIdentityHandlerService', fakeAsync(() => {
    const { oauthService, appState, appConfig, errors, ui } = buildMocks();
    const provider = new OidcIdentityProviderService(oauthService as any, appConfig, appState, errors, ui);

    const result = provider.accept('oidc', 'main');
    tick(); // resolve loadDiscoveryDocumentAndTryLogin promise

    expect(result).toBeTruthy();
    expect(result instanceof OidcIdentityHandlerService).toBeTrue();
  }));

  it('accept with non-oidc type returns null', () => {
    const { oauthService, appState, appConfig, errors, ui } = buildMocks();
    const provider = new OidcIdentityProviderService(oauthService as any, appConfig, appState, errors, ui);

    expect(provider.accept('saml', 'main')).toBeNull();
  });
});

describe('OidcIdentityHandlerService', () => {
  let handler: OidcIdentityHandlerService;
  let eventSubject: Subject<any>;
  let oauthService: jasmine.SpyObj<any>;
  let userInfoSpy: { set: jasmine.Spy };
  let ui: jasmine.SpyObj<IdentityUiPort>;

  beforeEach(() => {
    const mocks = buildMocks();
    eventSubject = mocks.eventSubject;
    oauthService = mocks.oauthService;
    userInfoSpy = mocks.userInfoSpy;
    ui = mocks.ui;
    handler = new OidcIdentityHandlerService(
      'main',
      oauthService,
      mocks.appConfig,
      mocks.appState,
      mocks.errors,
      mocks.ui,
    );
  });

  // ── Basic methods ──────────────────────────────────────────────────────────

  it('bootstrap() returns the boostrapSubject observable', () => {
    let emitted = false;
    handler.bootstrap().subscribe(() => {
      emitted = true;
    });
    eventSubject.next({ type: 'token_refresh_error' });
    expect(emitted).toBeTrue();
  });

  it('login() calls oauthService.initCodeFlow()', () => {
    handler.login();
    expect(oauthService.initCodeFlow).toHaveBeenCalled();
  });

  it('logout() goes to the end_session_endpoint without calling the revocation endpoint', () => {
    handler.logout();
    expect(oauthService.logOut).toHaveBeenCalledWith();
    expect(oauthService.revokeTokenAndLogout).not.toHaveBeenCalled();
  });

  // ── Event handling ─────────────────────────────────────────────────────────

  describe('event subscription', () => {
    it('user_profile_loaded is a no-op', () => {
      expect(() => eventSubject.next({ type: 'user_profile_loaded' })).not.toThrow();
    });

    it('discovery_document_loaded is a no-op', () => {
      expect(() => eventSubject.next({ type: 'discovery_document_loaded' })).not.toThrow();
    });

    it('token_received when currentUser.authenticated is falsy calls incomingLogin → sets userInfo to {}', () => {
      // currentUser = {} (initial) → authenticated undefined → falsy → incomingLogin()
      // incomingLogin: valid=false, logged=undefined → valid != logged → valid=false → sets {}
      oauthService.hasValidAccessToken.and.returnValue(false);
      eventSubject.next({ type: 'token_received' });
      expect(userInfoSpy.set).toHaveBeenCalledWith({});
    });

    it('token_received when currentUser.authenticated is true updates token without re-fetching profile', fakeAsync(() => {
      // Set currentUser.authenticated=true via silently_refreshed + valid token
      oauthService.hasValidAccessToken.and.returnValue(true);
      eventSubject.next({ type: 'silently_refreshed' });
      tick(); // resolve loadUserProfile promise
      userInfoSpy.set.calls.reset();
      oauthService.getAccessToken.and.returnValue('new-token');

      eventSubject.next({ type: 'token_received' });

      expect(userInfoSpy.set).toHaveBeenCalledWith(
        jasmine.objectContaining({ token: 'new-token', authenticated: true }),
      );
      expect(oauthService.loadUserProfile).toHaveBeenCalledTimes(1); // only from silently_refreshed
    }));

    it('logout event sets userInfo to {}', () => {
      eventSubject.next({ type: 'logout' });
      expect(userInfoSpy.set).toHaveBeenCalledWith({});
    });

    it('invalid_nonce_in_state calls initCodeFlow()', () => {
      eventSubject.next({ type: 'invalid_nonce_in_state' });
      expect(oauthService.initCodeFlow).toHaveBeenCalled();
    });

    it('silently_refreshed with invalid token → incomingLogin sets userInfo to {} and emits bootstrap', (done) => {
      oauthService.hasValidAccessToken.and.returnValue(false);
      handler.bootstrap().subscribe(() => {
        expect(userInfoSpy.set).toHaveBeenCalledWith({});
        done();
      });
      eventSubject.next({ type: 'silently_refreshed' });
    });

    it('silently_refreshed with valid token loads user profile and sets currentUser', fakeAsync(() => {
      oauthService.hasValidAccessToken.and.returnValue(true);
      eventSubject.next({ type: 'silently_refreshed' });
      tick();

      expect(oauthService.loadUserProfile).toHaveBeenCalled();
      expect(userInfoSpy.set).toHaveBeenCalledWith(
        jasmine.objectContaining({ authenticated: true, name: 'Test User', roles: ['admin'] }),
      );
    }));

    it('silently_refreshed with valid token and no groups defaults roles to ["guest"]', fakeAsync(() => {
      const mocks = buildMocks({ hasValidToken: true, userProfile: { name: 'Test', email: 'test@test.com' } });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      mocks.eventSubject.next({ type: 'silently_refreshed' });
      tick();

      expect(mocks.userInfoSpy.set).toHaveBeenCalledWith(jasmine.objectContaining({ roles: ['guest'] }));
    }));

    it('silently_refreshed is a no-op when logged state has not changed', () => {
      // First emission sets logged = false
      oauthService.hasValidAccessToken.and.returnValue(false);
      eventSubject.next({ type: 'silently_refreshed' });
      userInfoSpy.set.calls.reset();

      // Second emission: valid(false) === logged(false) → no-op
      eventSubject.next({ type: 'silently_refreshed' });
      expect(userInfoSpy.set).not.toHaveBeenCalled();
    });

    it('token_refresh_error resets currentUser and emits bootstrap', (done) => {
      handler.bootstrap().subscribe(() => {
        expect(userInfoSpy.set).toHaveBeenCalledWith({});
        done();
      });
      eventSubject.next({ type: 'token_refresh_error' });
    });

    it('discovery_document_load_error asks through the UI port and, if accepted, clears credentials and emits bootstrap', () => {
      let bootstrapEmitted = false;
      handler.bootstrap().subscribe(() => {
        bootstrapEmitted = true;
      });
      eventSubject.next({ type: 'discovery_document_load_error' });
      expect(ui.confirmResetCredentials).toHaveBeenCalledWith('discovery');
      expect(oauthService.logOut).toHaveBeenCalledWith(true);
      expect(bootstrapEmitted).toBeTrue();
      expect(userInfoSpy.set).toHaveBeenCalledWith({});
    });

    it('user_profile_load_error asks through the UI port with the profile reason', () => {
      eventSubject.next({ type: 'user_profile_load_error' });
      expect(ui.confirmResetCredentials).toHaveBeenCalledWith('profile');
      expect(oauthService.logOut).toHaveBeenCalledWith(true);
      expect(userInfoSpy.set).toHaveBeenCalledWith({});
    });

    it('keeps the credentials when the reset is cancelled', () => {
      ui.confirmResetCredentials.and.returnValue(of(false));
      let bootstrapEmitted = false;
      handler.bootstrap().subscribe(() => {
        bootstrapEmitted = true;
      });
      eventSubject.next({ type: 'user_profile_load_error' });
      expect(oauthService.logOut).not.toHaveBeenCalled();
      expect(userInfoSpy.set).not.toHaveBeenCalled();
      expect(bootstrapEmitted).toBeFalse();
    });

    it('code_error notifies through the UI port', () => {
      eventSubject.next({ type: 'code_error' });
      expect(ui.notifyError).toHaveBeenCalledWith('code');
    });

    it('never uses native alert/confirm', () => {
      spyOn(window, 'alert');
      spyOn(window, 'confirm');
      ['user_profile_load_error', 'code_error', 'discovery_document_load_error'].forEach((type) =>
        eventSubject.next({ type }),
      );
      expect(window.alert).not.toHaveBeenCalled();
      expect(window.confirm).not.toHaveBeenCalled();
    });

    it('silent_refresh_error calls logOut(true) and sets userInfo to {}', () => {
      eventSubject.next({ type: 'silent_refresh_error' });
      expect(oauthService.logOut).toHaveBeenCalledWith(true);
      expect(userInfoSpy.set).toHaveBeenCalledWith({});
    });

    it('ignores unknown events without logging them', () => {
      spyOn(console, 'log');
      eventSubject.next({ type: 'some_unknown_event' });
      eventSubject.next({ type: 'token_expires', info: 'access_token' });
      expect(console.log).not.toHaveBeenCalled();
      expect(oauthService.refreshToken).not.toHaveBeenCalled();
    });
  });

  // ── configure() / configureForTenant() ────────────────────────────────────

  describe('configure() and configureForTenant()', () => {
    it('sets customQueryParams when audience is present', fakeAsync(() => {
      const mocks = buildMocks({
        identitySetup: {
          redirect: 'http://localhost/callback',
          issuer: 'https://issuer.example.com',
          'force-https': true,
          'client-id': 'cid',
          scope: 'openid',
          audience: 'my-api',
        },
      });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      expect(mocks.oauthService.configure).toHaveBeenCalledWith(
        jasmine.objectContaining({ customQueryParams: { audience: 'my-api' }, requireHttps: true }),
      );
    }));

    it('does not set customQueryParams when audience is absent', fakeAsync(() => {
      const mocks = buildMocks();
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      const arg = mocks.oauthService.configure.calls.mostRecent().args[0];
      expect(arg.customQueryParams).toBeUndefined();
    }));

    it('uses logout-redirect as postLogoutRedirectUri', fakeAsync(() => {
      const mocks = buildMocks({
        identitySetup: {
          redirect: 'http://localhost/callback',
          'logout-redirect': 'http://localhost/',
          issuer: 'https://issuer.example.com',
          'client-id': 'cid',
          scope: 'openid',
        },
      });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      const arg = mocks.oauthService.configure.calls.mostRecent().args[0];
      expect(arg.postLogoutRedirectUri).toBe('http://localhost/');
    }));

    it('falls back to the origin root as postLogoutRedirectUri', fakeAsync(() => {
      const mocks = buildMocks();
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      const arg = mocks.oauthService.configure.calls.mostRecent().args[0];
      expect(arg.postLogoutRedirectUri).toBe(window.location.origin + '/');
    }));

    it('uses localStorage when persistent is true', fakeAsync(() => {
      const mocks = buildMocks({
        identitySetup: {
          redirect: 'http://localhost/callback',
          issuer: 'https://issuer.example.com',
          'force-https': false,
          'client-id': 'cid',
          scope: 'openid',
          persistent: true,
        },
      });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      expect(mocks.oauthService.setStorage).toHaveBeenCalledWith(localStorage);
    }));

    it('uses sessionStorage when persistent is absent', fakeAsync(() => {
      const mocks = buildMocks();
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      expect(mocks.oauthService.setStorage).toHaveBeenCalledWith(sessionStorage);
    }));

    it('uses redirectUri from setup when redirect is provided', fakeAsync(() => {
      const mocks = buildMocks();
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      expect(mocks.oauthService.configure).toHaveBeenCalledWith(
        jasmine.objectContaining({ redirectUri: 'http://localhost/callback' }),
      );
    }));

    it('uses window.location as redirectUri when redirect is absent', fakeAsync(() => {
      const mocks = buildMocks({
        identitySetup: {
          issuer: 'https://issuer.example.com',
          'force-https': false,
          'client-id': 'cid',
          scope: 'openid',
        },
      });
      const expectedUrl =
        window.location.protocol + '//' + window.location.host + window.location.pathname + window.location.search;
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      expect(mocks.oauthService.configure).toHaveBeenCalledWith(jasmine.objectContaining({ redirectUri: expectedUrl }));
    }));

    it('forCurrent replaces {{tenant}} placeholder in issuer', fakeAsync(() => {
      const mocks = buildMocks({
        tenant: 'acme',
        identitySetup: {
          redirect: 'http://localhost/callback',
          issuer: 'https://{{tenant}}.auth.example.com',
          'force-https': false,
          'client-id': 'cid',
          scope: 'openid',
        },
      });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      expect(mocks.oauthService.configure).toHaveBeenCalledWith(
        jasmine.objectContaining({ issuer: 'https://acme.auth.example.com' }),
      );
    }));

    it('loadDiscoveryDocumentAndTryLogin resolving triggers incomingLogin', fakeAsync(() => {
      const mocks = buildMocks({ hasValidToken: false });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      // incomingLogin: valid=false, logged=undefined → enters if → sets userInfo to {}
      expect(mocks.userInfoSpy.set).toHaveBeenCalledWith({});
    }));

    function configureWith(setup: any, hasValidToken = false) {
      const mocks = buildMocks({
        hasValidToken,
        identitySetup: { issuer: 'https://issuer.example.com', 'client-id': 'cid', scope: 'openid', ...setup },
      });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();
      return { mocks, config: mocks.oauthService.configure.calls.mostRecent().args[0] };
    }

    it('uses the configured scope as is', fakeAsync(() => {
      const { config } = configureWith({ scope: 'openid profile offline_access' });
      expect(config.scope).toBe('openid profile offline_access');
    }));

    it('always enables PKCE and warns when the pkce option is present', fakeAsync(() => {
      spyOn(console, 'warn');
      const { config } = configureWith({ pkce: false });
      expect(config.disablePKCE).toBeFalse();
      expect(console.warn).toHaveBeenCalled();
    }));

    it('does not show debug information unless debug is true', fakeAsync(() => {
      expect(configureWith({}).config.showDebugInformation).toBeFalse();
    }));

    it('only uses localStorage when persistent is exactly true', fakeAsync(() => {
      const { mocks } = configureWith({ persistent: 'true' });
      expect(mocks.oauthService.setStorage).toHaveBeenCalledWith(sessionStorage);
    }));

    it('refreshes with the refresh token through the automatic refresh only', fakeAsync(() => {
      const { mocks, config } = configureWith({});
      expect(config.useSilentRefresh).toBeFalse();
      expect(mocks.oauthService.setupAutomaticSilentRefresh).toHaveBeenCalled();
    }));

    it('reads the roles from the configured roles-claim', fakeAsync(() => {
      const mocks = buildMocks({
        hasValidToken: true,
        identitySetup: { issuer: 'https://issuer.example.com', 'client-id': 'cid', 'roles-claim': 'roles' },
        userProfile: { name: 'Test', groups: ['admin'], roles: ['editor'] },
      });
      const h = new OidcIdentityHandlerService(
        'main',
        mocks.oauthService,
        mocks.appConfig,
        mocks.appState,
        mocks.errors,
        mocks.ui,
      );
      h.configure();
      tick();

      expect(mocks.userInfoSpy.set).toHaveBeenCalledWith(jasmine.objectContaining({ roles: ['editor'] }));
    }));
  });
});
